export const requestForToken = async () => {
  if (!messaging) return null;
  try {
    // Explicitly request notification permission from the browser
    const permission = await Notification.requestPermission();
    if (permission !== 'granted') {
      console.log('Notification permission not granted.');
      return null;
    }

    // Register the service worker (must be served from the site root)
    let registration = null;
    if ('serviceWorker' in navigator) {
      try {
        registration = await navigator.serviceWorker.register('/firebase-messaging-sw.js');
        console.log('Service worker registered for FCM:', registration);
      } catch (swErr) {
        console.warn('Service worker registration failed:', swErr);
      }
    }

    const currentToken = await getToken(messaging, {
      vapidKey: "BAtngqANTm4hqsfJirncDxyHeS6ghRBFvgXYXi7iJ_I4mQ1bMhGHe20mUWV0YZIcUGjQN8-upn8udKlVdL_FNWU",
      serviceWorkerRegistration: registration
    });
    if (currentToken) {
      console.log('Current token for client: ', currentToken);
      return currentToken;
    } else {
      console.log('No registration token available. Request permission to generate one.');
      return null;
    }
  } catch (err) {
    console.log('An error occurred while retrieving token. ', err);
    throw err;
  }
};

export const onMessageListener = (callback) => {
  if (messaging) {
    return onMessage(messaging, (payload) => {
      callback(payload);
    });
  }
};

